function trainingRecords(){
 const rides=cyclingRides().filter(w=>w.type!=='rullo'),longest=Math.max(0,...rides.map(w=>Number(w.distance)||0)),climb=Math.max(0,...rides.map(w=>Number(w.elevation)||0)),tot=rides.reduce((a,w)=>a+(Number(w.distance)||0),0),strength=data.workouts.filter(w=>w.type==='forza').length;
 const goals=[20,50,100].map(n=>({name:n+' km in una uscita',done:longest>=n}));
 main.innerHTML=`<div class="pageHeading"><span class="eyebrow">I TUOI TRAGUARDI</span><h2>Record personali</h2><p>Risultati calcolati dalle attività registrate, senza modificare i dati.</p></div><div class="grid two"><div class="metric"><small>Uscita più lunga</small><strong>${longest.toFixed(1)} km</strong></div><div class="metric"><small>Dislivello record</small><strong>${climb.toFixed(0)} m</strong></div><div class="metric"><small>Km outdoor totali</small><strong>${tot.toFixed(0)} km</strong></div><div class="metric"><small>Sessioni forza</small><strong>${strength}</strong></div></div><div class="card"><h2>Traguardi ciclismo</h2>${goals.map(g=>`<div class="row achievement"><span>${g.done?'🏆':'○'} ${g.name}</span><strong>${g.done?'Raggiunto':'Da raggiungere'}</strong></div>`).join('')}</div><button class="secondary" data-go="cyclingDashboard" style="width:100%">Apri Bike Performance</button>`;
}
